function jdFlatten(o, prefix, out){
  out = out || {};
  prefix = prefix || '';
  if(o===null || typeof o !== 'object'){ out[prefix] = o; return out; }
  if(Array.isArray(o)){
    for(var i=0;i<o.length;i++) jdFlatten(o[i], prefix+'/'+i, out);
  } else {
    var keys = Object.keys(o);
    if(keys.length===0 && prefix!==''){ out[prefix] = {}; return out; }
    for(var k=0;k<keys.length;k++){ var key=keys[k]; jdFlatten(o[key], prefix?prefix+'.'+key:key, out); }
  }
  return out;
}
function jdEqual(a,b){
  if(a===b) return true;
  if(a===null||b===null||typeof a!=='object'||typeof b!=='object') return a===b;
  var ka=Object.keys(a), kb=Object.keys(b);
  if(ka.length!==kb.length) return false;
  for(var i=0;i<ka.length;i++){ if(!jdEqual(a[ka[i]], b[ka[i]])) return false; }
  return true;
}
function jdDiff(a,b){
  var fa=jdFlatten(a), fb=jdFlatten(b), paths={}, out={added:[],removed:[],changed:[]};
  var p;
  for(p in fa) paths[p]=1;
  for(p in fb) paths[p]=1;
  for(p in paths){
    var inA=fa.hasOwnProperty(p), inB=fb.hasOwnProperty(p);
    if(inA && !inB) out.removed.push(p);
    else if(!inA && inB) out.added.push(p);
    else if(!jdEqual(fa[p], fb[p])) out.changed.push({path:p, a:fa[p], b:fb[p]});
  }
  out.added.sort(); out.removed.sort();
  out.changed.sort(function(x,y){ return x.path<y.path?-1:(x.path>y.path?1:0); });
  out.total = out.added.length+out.removed.length+out.changed.length;
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { jdFlatten:jdFlatten, jdEqual:jdEqual, jdDiff:jdDiff };
}
if (typeof window !== 'undefined') {
  window.JsonDiffForgePure = { jdFlatten:jdFlatten, jdEqual:jdEqual, jdDiff:jdDiff };
}
